candidate_patches.mixed-retry.patch:
--- a/PhoneGigaAm.java
+++ b/PhoneGigaAm.java
@@ -76,6 +76,9 @@
                         if (level < .05f || weak(words)) {
                             job.check();
                             float[] clean = PhoneSpeechWindow.clean(raw);
+                            float[] normalized = raw.clone();
+                            PhoneSpeechWindow.normalize(normalized, level, 32);
+                            for (int i = 0; i < clean.length; i++) clean[i] = (clean[i] + normalized[i]) * .5f;
                             JSONArray alternate = recognize(environment, frontend, acoustic, clean, tokens, offset, first, last, true);
                             reconcile(words, alternate);
                         }

